#!/usr/bin/env node
// Refresh the updater signatures inside the release's latest.json after
// artifacts have been repacked (AppImage xz, deb xz, ...).
//
// Tauri's signer writes `<asset>.sig` next to every repacked file; this script
// maps those signatures back onto the platform entries of latest.json by
// matching the URL basename. Entries whose artifact was not repacked keep the
// signature generated by tauri-action.
//
// Usage: node scripts/shrink/patch-latest-json.mjs <dir-with-assets-and-sigs>
// Env: GH_TOKEN, GITHUB_REF_NAME, GITHUB_REPOSITORY

import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { basename, join } from "node:path";

const assetDir = process.argv[2];
const tag = process.env.GITHUB_REF_NAME;
const repo = process.env.GITHUB_REPOSITORY;

if (!assetDir || !tag || !repo) {
  console.error("usage: GH_TOKEN=... GITHUB_REF_NAME=... GITHUB_REPOSITORY=... patch-latest-json.mjs <dir>");
  process.exit(1);
}

const gh = (args) => execFileSync("gh", args, { encoding: "utf8" });
const signatures = new Map(
  readdirSync(assetDir)
    .filter((name) => name.endsWith(".sig"))
    .map((name) => [name.slice(0, -4), readFileSync(join(assetDir, name), "utf8").trim()]),
);

if (signatures.size === 0) {
  console.log("patch-latest-json: no .sig files next to repacked assets, nothing to do");
  process.exit(0);
}

const work = mkdtempSync(join(tmpdir(), "dbx-latest-json-"));
try {
  gh(["release", "download", tag, "--repo", repo, "--pattern", "latest.json", "--dir", work, "--clobber"]);
  const path = join(work, "latest.json");
  const manifest = JSON.parse(readFileSync(path, "utf8"));

  let updated = 0;
  for (const entry of Object.values(manifest.platforms ?? {})) {
    if (!entry?.url) continue;
    const file = basename(entry.url.split("?")[0]);
    const signature = signatures.get(file);
    if (signature) {
      entry.signature = signature;
      updated += 1;
    }
  }

  if (updated === 0) {
    console.log("patch-latest-json: no latest.json entry matches the repacked assets");
    process.exit(0);
  }

  writeFileSync(path, `${JSON.stringify(manifest, null, 2)}\n`);
  gh(["release", "upload", tag, path, "--repo", repo, "--clobber"]);
  console.log(`patch-latest-json: refreshed ${updated} signature(s) in latest.json`);
} finally {
  rmSync(work, { recursive: true, force: true });
}
